const input = $input.first().json;
const transcript = input.transcript || '';
const history = input.args?.history || [];
const messages = [
  { role: 'system', content: 'You are NEXUS, a helpful voice assistant. Keep responses concise and conversational. You are speaking aloud, so avoid markdown, code blocks, or long lists.' },
  ...history,
  { role: 'user', content: transcript }
];
return [{ json: { messages: messages } }];
